-- Expand the one-line APAC map project descriptions into a few sentences.
-- Only items still carrying their original seed id AND original text are rewritten; anything edited in /admin/map is kept.
UPDATE "site_content"
SET "value" = jsonb_set(
  "value",
  '{items}',
  (
    SELECT COALESCE(jsonb_agg(
      CASE
          WHEN e->>'id' = 'seed-A' AND e->>'text' = 'Build MVNE platform, launch a fighter sub-brand and complete Prepaid migration for M1 Singapore' THEN e || jsonb_build_object('text', 'Build MVNE platform, launch a fighter sub-brand and complete Prepaid migration for M1 Singapore. The multi-tenant platform launched MVNOs for MyRepublic, Gorilla Mobile, Geenet and Changi Mobile, plus M1''s own fighter brand Maxx, in roughly 18 months. It came with digital KYC self-onboarding and two major platform migrations in one year, with zero customer-visible downtime.')
          WHEN e->>'id' = 'seed-B' AND e->>'text' = 'Secure and deploy the largest Wi-Fi network in Malaysia for TM (Telekom Malaysia)' THEN e || jsonb_build_object('text', 'Secure and deploy the largest Wi-Fi network in Malaysia for TM (Telekom Malaysia). A carrier-scale Wi-Fi network has to authenticate and protect a very large number of users and hotspots, so security mattered as much as coverage. The work took the network from design through secure rollout for the country''s national operator.')
          WHEN e->>'id' = 'seed-C' AND e->>'text' = 'Ads-sponsored and Residential Wi-Fi Offload for STP Tower in Indonesia' THEN e || jsonb_build_object('text', 'Ads-sponsored and Residential Wi-Fi Offload for STP Tower in Indonesia. Wi-Fi offload moves mobile data traffic onto Wi-Fi to relieve congested cellular networks. The solution combined ad-sponsored public access, where advertisers fund free connectivity, with offload through residential Wi-Fi.')
          WHEN e->>'id' = 'seed-D' AND e->>'text' = 'Prepaid platform support and growth for Celcom Malaysia' THEN e || jsonb_build_object('text', 'Prepaid platform support and growth for Celcom Malaysia. Prepaid depends on a charging platform that rates and balances every call and data session in real time, so reliability is non-negotiable. The work kept that platform healthy while helping it grow with new plans and offers.')
          WHEN e->>'id' = 'seed-E' AND e->>'text' = 'Prepaid platform support and growth for Telstra and Optus' THEN e || jsonb_build_object('text', 'Prepaid platform support and growth for Telstra and Optus. Supporting two of Australia''s largest operators meant keeping a real-time charging platform dependable at scale. It also meant evolving it as new plans, bundles and offers came to market.')
          WHEN e->>'id' = 'seed-F' AND e->>'text' = 'Deploy CDMA to GSM and GSM Dual-IMSI Roaming for Spark NZ' THEN e || jsonb_build_object('text', 'Deploy CDMA to GSM and GSM Dual-IMSI Roaming for Spark NZ. Spark, formerly Telecom NZ, was moving subscribers from a CDMA network to GSM, so service had to keep working while the network changed underneath them. Dual-IMSI roaming puts two network identities on one SIM, which lets a traveller use local rates abroad.')
          WHEN e->>'id' = 'seed-G' AND e->>'text' = 'Prepaid Migration for Vodafone NZ' THEN e || jsonb_build_object('text', 'Prepaid Migration for Vodafone NZ. Migrating a prepaid base means moving balances, bundles and customer histories to a new platform without anyone losing credit or service. Done well, customers barely notice that it happened.')
          WHEN e->>'id' = 'seed-H' AND e->>'text' = 'Prepaid Migration for Far EasTone (FET)' THEN e || jsonb_build_object('text', 'Prepaid Migration for Far EasTone (FET). The migration moved prepaid customers onto a new platform while protecting their balances, bundles and active services. It required careful planning of the cutover so that top-ups and usage kept working throughout.')
          WHEN e->>'id' = 'seed-I' AND e->>'text' = 'Secure and roll out the world-first WRIX-based Wi-Fi Roaming Hub for China Mobile' THEN e || jsonb_build_object('text', 'Secure and roll out the world-first WRIX-based Wi-Fi Roaming Hub for China Mobile. WRIX is the Wireless Broadband Alliance''s standard for exchanging Wi-Fi roaming traffic and settlement data between operators. The hub let users roam across partner networks on a single account.')
          WHEN e->>'id' = 'seed-J' AND e->>'text' = 'Roll out Policy Manager (PCRF) for Softbank' THEN e || jsonb_build_object('text', 'Roll out Policy Manager (PCRF) for Softbank. A PCRF is the part of the mobile core that decides what each subscriber and session is allowed to do, at what speed and at what charge. It is how fair-usage rules and plan entitlements are enforced in real time across the network.')
          WHEN e->>'id' = 'seed-K' AND e->>'text' = 'Roll out Prepaid Charging for Sun Cellular (now Smart)' THEN e || jsonb_build_object('text', 'Roll out Prepaid Charging for Sun Cellular (now Smart). Prepaid charging deducts credit in real time as customers call, text and use data, so accuracy and speed matter on every transaction. The rollout put that engine in place for a large prepaid customer base.')
          WHEN e->>'id' = 'seed-L' AND e->>'text' = 'Wi-Fi Offload for PTCL, Mobilink and Wateen Telecom' THEN e || jsonb_build_object('text', 'Wi-Fi Offload for PTCL, Mobilink and Wateen Telecom. Offload moves data traffic from congested mobile networks onto Wi-Fi to improve customer experience and relieve capacity. The work covered three operators (Mobilink is now Jazz), each with its own network and commercial needs.')
          WHEN e->>'id' = 'seed-M' AND e->>'text' = 'Supply major outdoor Wi-Fi to Myanmar Net' THEN e || jsonb_build_object('text', 'Supply major outdoor Wi-Fi to Myanmar Net. Outdoor Wi-Fi at scale has to cope with weather, power and backhaul constraints that indoor networks never face. The project supplied the wireless infrastructure to bring dependable public coverage to the operator''s customers.')
          WHEN e->>'id' = 'seed-N' AND e->>'text' = 'Live trial of Intelligent Wi-Fi Traffic Steering for Bhutan Telecom' THEN e || jsonb_build_object('text', 'Live trial of Intelligent Wi-Fi Traffic Steering for Bhutan Telecom. Traffic steering guides devices to the best available connection, Wi-Fi or cellular, based on real network conditions rather than signal strength alone. The trial ran on the live network, proving the approach with real customers before any wider rollout.')
          WHEN e->>'id' = 'seed-O' AND e->>'text' = 'Roll out Broadband Policy Manager (PCRF) for Sri Lanka Telecom (SLT)' THEN e || jsonb_build_object('text', 'Roll out Broadband Policy Manager (PCRF) for Sri Lanka Telecom (SLT). On a broadband network the policy manager applies each customer''s plan, speed and fair-usage rules automatically. It gives the operator control over how capacity is shared and how packages are enforced.')
          WHEN e->>'id' = 'seed-P' AND e->>'text' = 'Lead the full-stack BSS transformation (CRM, Product Catalog, Billing & Charging and integrations) for Maxis' THEN e || jsonb_build_object('text', 'Lead the full-stack BSS transformation (CRM, Product Catalog, Billing & Charging and integrations) for Maxis. I''m accountable end to end, from scope, architecture and vendors through to cutover and business readiness. The goal is a migration that protects revenue and customer experience.')
        ELSE e
      END
      ORDER BY ord
    ), '[]'::jsonb)
    FROM jsonb_array_elements("value"->'items') WITH ORDINALITY AS t(e, ord)
  )
)
WHERE "key" = 'apac_map' AND jsonb_typeof("value"->'items') = 'array';
